/// only the guest owner reference and security/audit metadata for the
/// session lifecycle.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_guest_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owning guest's {@link todo_app_guests.id}.
  todo_app_guest_id String @db.Uuid

  /// IP address observed when the guest session was created.
  ip String

  /// Current or last visited URL associated with the guest session.
  href String

  /// Referrer URL associated with the guest session request.
  referrer String

  /// Timestamp when the guest session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the guest session expires.
  expired_at DateTime @db.Timestamptz

  /// Timestamp when the guest session record was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the guest session was soft deleted, if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
