schemas.schema-03-todos.prisma:
/// Stores each member's private todo item, including ownership, title,
/// optional description, optional start and due dates, completion state, and
/// soft-delete status.
///
/// This table is the current-state record for a todo. It supports private
/// list browsing, detail viewing, completion toggling, editing, trash
/// management, restore, and permanent deletion workflows. Edit history is
/// preserved in the separate {@link todo_app_todo_histories} table, so this
/// model only contains the latest todo state.
///
/// @namespace Todos
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_todos {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owning member account's {@link todo_app_members.id}.
  todo_app_member_id String @db.Uuid

  /// Todo title shown in todo lists and detail views.
  title String

  /// Optional todo description shown in the detail view.
  description String?

  /// Optional start date for the todo.
  start_at DateTime? @db.Timestamptz

  /// Optional due date for the todo.
  due_at DateTime? @db.Timestamptz

  /// Whether the todo is currently completed.
  is_completed Boolean

  /// When this todo record was created.
  created_at DateTime @db.Timestamptz

  /// When this todo record was last updated.
  updated_at DateTime @db.Timestamptz

  /// When this todo was soft deleted; null means it is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  member todo_app_members @relation(fields: [todo_app_member_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  histories todo_app_todo_histories[]

  //----
  // INDEXES
  //----
  @@index([todo_app_member_id, deleted_at, created_at])
  // spellchecker: ignore-next-line
  @@index([todo_app_member_id, deleted_at, is_completed, created_at], map: "todo_app_todos_todo_app_member_id_deleted_at_is_comple_b1322872")
  @@index([todo_app_member_id, deleted_at, start_at])
  @@index([todo_app_member_id, deleted_at, due_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-04-todo-history.prisma:
/// Stores one immutable edit-history entry for a todo item. Each row records
/// when an edit occurred and the resulting title, description, start date,
/// and due date values for the changed fields so the full change trail can
/// be viewed in chronological order.
///
/// This table is a historical snapshot trail for {@link todo_app_todos} and
/// is only meaningful in the context of its parent todo. It is append-only
/// by design and supports the private todo app’s requirement to preserve the
/// edit history of each user-owned todo until the parent todo is permanently
/// removed.
///
/// @namespace TodoHistory
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_todo_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent todo for this history entry. References {@link todo_app_todos.id}.
  todo_app_todo_id String @db.Uuid

  /// Timestamp when this history entry was recorded for the todo edit.
  edited_at DateTime @db.Timestamptz

  /// Todo title after the edit, if the title was changed as part of this
  /// history entry.
  title String?

  /// Todo description after the edit, if the description was changed as part
  /// of this history entry.
  description String?

  /// Todo start date after the edit, if the start date was changed as part of
  /// this history entry.
  start_date DateTime? @db.Timestamptz

  /// Todo due date after the edit, if the due date was changed as part of this
  /// history entry.
  due_date DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  todo todo_app_todos @relation(fields: [todo_app_todo_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@index([todo_app_todo_id, edited_at])
}

schemas.schema-02-user-profile.prisma:
