  );
  TestValidator.equals(
    "todo start date preserved after reverting completion",
    reverted.start_at,
    start_at,
  );
  TestValidator.equals(
    "todo due date preserved after reverting completion",
    reverted.due_at,
    due_at,
  );
  TestValidator.equals(
    "todo marked incomplete again",
    reverted.is_completed,
    false,
  );
}

