      due_at: true,
      created_at: true,
      deleted_at: true,
      member: {
        select: {
          id: true,
          email: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
        },
      },
    },
  });
  const records = await MyGlobal.prisma.todo_app_todos.count({ where });
  return {
    data: data.map((todo) => ({
