        due_at: history.todo.due_at?.toISOString() ?? null,
        created_at: history.todo.created_at.toISOString(),
        deleted_at: history.todo.deleted_at?.toISOString() ?? null,
      },
    })),
    pagination: {
      current: page,
      limit,
      records,
      pages: Math.ceil(records / limit),
    },
  };
}

